const body = $json.body || $json;
const answers = body.answers || {};
const utm = body.utm || {};
const initialRoute = body.recommended_route || "/oferta-start";
const nome = (body.name || body.full_name || body.nome || "Personal").trim();
const primeiroNome = nome.split(" ")[0] || "Personal";
const email = (body.email || "").trim();
const rawPhone = (body.phone || body.whatsapp || body.telefone || "").trim();
let phoneClean = rawPhone.replace(/\D/g, "");
if (phoneClean.length === 10 || phoneClean.length === 11) {
  phoneClean = "55" + phoneClean;
}

// Dicionário completo das respostas estratégicas do Quiz
const DICT = {
  q1: {
    pergunta: "Quantidade de Alunos",
    opcoes: {
      A: "Ainda não tem alunos / conquistando primeiros",
      B: "De 1 a 9 alunos",
      C: "De 10 a 30 alunos",
      D: "Mais de 30 alunos"
    }
  },
  q2: {
    pergunta: "Entrega Atual de Treinos",
    opcoes: {
      A: "Planilhas ou documentos",
      B: "WhatsApp / mensagens individuais",
      C: "Aplicativo de prescrição",
      D: "Ferramentas dispersas e descentralizadas"
    }
  },
  q3: {
    pergunta: "Modelo de Atendimento",
    opcoes: {
      A: "Principalmente presencial",
      B: "Consultoria online",
      C: "Híbrido (presencial + online)",
      D: "Ainda estruturando modelo"
    }
  },
  q4: {
    pergunta: "Meta Principal em 12 Meses",
    opcoes: {
      A: "Conquistar primeiros alunos",
      B: "Aumentar carteira e faturamento",
      C: "Organizar operação com eficiência",
      D: "Fortalecer marca e autoridade"
    }
  },
  q7: {
    pergunta: "Tempo Gasto por Prescrição",
    opcoes: {
      A: "Até 3 minutos (rápido)",
      B: "Entre 4 e 10 minutos",
      C: "Entre 11 e 20 minutos",
      D: "Mais de 20 minutos (Gargalo severo de tempo)"
    }
  },
  q13: {
    pergunta: "Preferencia sobre Marca no App",
    opcoes: {
      A: "Não se importa com a marca",
      B: "Prefere a marca oficial da plataforma",
      C: "Exige aplicativo com marca própria"
    }
  },
  q14: {
    pergunta: "Frustração com Outros Aplicativos",
    opcoes: {
      A: "Gostaria de marca própria, mas o concorrente não oferece",
      B: "Encontrou limitações de personalização e identidade visual",
      C: "Personalização não foi prioridade",
      D: "Não conhece plataformas o suficiente"
    }
  },
  q16: {
    pergunta: "Maior Interesse Imediato",
    opcoes: {
      A: "Prescrever treinos práticos e rápidos",
      B: "Organizar alunos e rotina em um só lugar",
      C: "Ter o app com sua identidade visual própria",
      D: "Adaptação da ferramenta à rotina profissional"
    }
  }
};

const dadosLegiveis = {
  quantidade_alunos: DICT.q1.opcoes[answers.q1] || answers.q1 || "Não informado",
  entrega_treinos_atual: DICT.q2.opcoes[answers.q2] || answers.q2 || "Não informado",
  modelo_atendimento: DICT.q3.opcoes[answers.q3] || answers.q3 || "Não informado",
  meta_12_meses: DICT.q4.opcoes[answers.q4] || answers.q4 || "Não informado",
  tempo_por_treino: DICT.q7.opcoes[answers.q7] || answers.q7 || "Não informado",
  desejo_marca_propria: DICT.q13.opcoes[answers.q13] || answers.q13 || "Não informado",
  dor_concorrentes: DICT.q14.opcoes[answers.q14] || answers.q14 || "Não informado",
  interesse_imediato: DICT.q16.opcoes[answers.q16] || answers.q16 || "Não informado"
};

return [{
  json: {
    lead_id: body.lead_id || "",
    nome: nome,
    primeiro_nome: primeiroNome,
    email: email,
    whatsapp: phoneClean,
    whatsapp_formatado: rawPhone,
    data_hora: body.created_at || new Date().toISOString(),
    rota_previa: initialRoute,
    dados_legiveis: dadosLegiveis,
    utm: utm,
    respostas_brutas: answers,
    prompt_analise: `Analise as respostas deste Personal Trainer e gere uma qualificação comercial precisa:\n- Nome: ${nome} (Primeiro nome: ${primeiroNome})\n- E-mail: ${email}\n- WhatsApp: ${rawPhone}\n- Volume de Alunos: ${dadosLegiveis.quantidade_alunos}\n- Método Atual de Entrega: ${dadosLegiveis.entrega_treinos_atual}\n- Modelo de Atendimento: ${dadosLegiveis.modelo_atendimento}\n- Meta nos Próximos 12 Meses: ${dadosLegiveis.meta_12_meses}\n- Tempo Médio por Treino: ${dadosLegiveis.tempo_por_treino}\n- Desejo de Marca Própria: ${dadosLegiveis.desejo_marca_propria}\n- Insatisfação com Outros Apps: ${dadosLegiveis.dor_concorrentes}\n- Maior Interesse no Treino Inteligente: ${dadosLegiveis.interesse_imediato}`
  }
}];

// Extrai e normaliza o JSON gerado pelo Agente de IA
const rawOutput = $json.output || $json.text || $json.content || JSON.stringify($json);
const leadAnterior = $('Decodificar & Estruturar Lead1').first().json;

let aiData = {};
try {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiData = JSON.parse(jsonMatch[0]);
  } else {
    aiData = JSON.parse(rawOutput);
  }
} catch (e) {
  const isPro = rawOutput.includes('/oferta-pro') || rawOutput.includes('Anual');
  aiData = {
    rota_recomendada: isPro ? '/oferta-pro' : '/oferta-start',
    oferta_nome: isPro ? 'Plano Anual com Sua Marca (R$ 497/ano)' : 'Plano Pro Mensal (R$ 44,90/mês)',
    perfil_resumo: 'Personal Trainer em busca de otimização e organização',
    score_maturidade: isPro ? 8 : 4,
    dor_principal: 'Prescrição demorada e atendimento disperso',
    gatilho_conversao: 'Prescrição em menos de 3 minutos no aplicativo com sua própria logo'
  };
}

// Garante rota estritamente válida
let rotaFinal = aiData.rota_recomendada;
if (rotaFinal !== '/oferta-pro' && rotaFinal !== '/oferta-start') {
  rotaFinal = leadAnterior.rota_previa || '/oferta-start';
}

const primeiroNome = leadAnterior.primeiro_nome || 'Personal';
const nomeCompleto = leadAnterior.nome || primeiroNome;
const ofertaNome = aiData.oferta_nome || (rotaFinal === '/oferta-pro' ? 'Plano Anual com Sua Marca (R$ 497/ano)' : 'Plano Pro Mensal (R$ 44,90/mês)');
const baseUrl = rotaFinal === '/oferta-pro' ? 'https://meuapp.treinointeligente.pro/oferta-pro' : 'https://meuapp.treinointeligente.pro/oferta-start';
const linkOferta = leadAnterior.lead_id ? `${baseUrl}?lead_id=${leadAnterior.lead_id}` : baseUrl;
const gatilho = aiData.gatilho_conversao || 'Prescrever fichas em 3 minutos e ter o app com o seu logotipo';
const dor = aiData.dor_principal || 'Tempo perdido na montagem e envio manual de treinos';

// 1. Mensagem de WhatsApp humana, persuasiva e formatada
const msgWhatsapp = `Fala ${primeiroNome}, tudo bem? 💪\n\nAqui é da equipe do *Treino Inteligente*.\n\nAcabei de receber o resultado do seu diagnóstico e seu perfil foi qualificado para o:\n🎯 *${ofertaNome}*\n\n⚡ *Ponto principal trabalhado:* ${dor}\n🚀 *Como vamos resolver:* ${gatilho}\n\nLiberamos para você uma condição exclusiva de *3 DIAS DE TESTE GRÁTIS (R$ 0,00 cobrados hoje)* no checkout, para você testar na prática e cadastrar seus alunos sem fidelidade.\n\n👉 *Toque no link abaixo para ver sua análise completa e ativar seu teste grátis:*\n${linkOferta}\n\nSe precisar de qualquer apoio na montagem do seu primeiro treino, é só responder direto aqui nesta mensagem!`;

// 2. Assunto e Corpo HTML do E-mail (Inline CSS profissional compatível com Gmail Web e Mobile)
const emailAssunto = `[Diagnóstico] ${primeiroNome}, sua análise oficial no Treino Inteligente está pronta`;

const emailCorpoHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Diagnóstico Oficial Treino Inteligente</title>
</head>
<body style="margin: 0; padding: 20px 10px; background-color: #0b0f19; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #1e293b;">
  <div style="max-width: 600px; margin: 0 auto; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 25px rgba(0,0,0,0.3); border: 1px solid #1e293b;">

    <!-- Cabeçalho -->
    <div style="background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%); padding: 32px 24px; text-align: center;">
      <div style="display: inline-block; background-color: rgba(16, 185, 129, 0.15); border: 1px solid rgba(16, 185, 129, 0.4); color: #10b981; font-size: 11px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase; padding: 6px 14px; border-radius: 999px; margin-bottom: 12px;">
        Diagnóstico Concluído
      </div>
      <h1 style="color: #ffffff; font-size: 24px; font-weight: 800; margin: 0; letter-spacing: -0.5px;">
        TREINO <span style="color: #10b981;">INTELIGENTE</span>
      </h1>
      <p style="color: #94a3b8; font-size: 13px; margin: 8px 0 0 0;">
        Prescrição em 3 minutos & Posicionamento Profissional
      </p>
    </div>

    <!-- Conteúdo Principal -->
    <div style="padding: 32px 28px; line-height: 1.6; font-size: 15px;">
      <p style="margin: 0 0 16px 0; font-size: 18px; color: #0f172a;">
        Olá, <strong>${primeiroNome}</strong>!
      </p>

      <p style="margin: 0 0 20px 0; color: #475569;">
        Analisamos com precisão as respostas que você enviou no questionário. Com base no seu volume de alunos e modelo de atendimento atual, identificamos exatamente o que você precisa para destravar tempo e valorizar a sua consultoria:
      </p>

      <!-- Card do Diagnóstico -->
      <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-left: 5px solid #10b981; border-radius: 12px; padding: 20px; margin: 24px 0;">
        <div style="font-size: 11px; font-weight: 800; color: #10b981; text-transform: uppercase; letter-spacing: 0.5px;">
          Plano Estratégico Indicado
        </div>
        <div style="font-size: 20px; font-weight: 800; color: #0f172a; margin: 6px 0;">
          ${ofertaNome}
        </div>
        <div style="font-size: 14px; color: #334155; margin-top: 10px;">
          <strong>Ponto de Atenção:</strong> ${dor}
        </div>
        <div style="font-size: 14px; color: #047857; margin-top: 6px;">
          <strong>Solução Imediata:</strong> ${gatilho}
        </div>
      </div>

      <p style="margin: 20px 0; color: #475569;">
        Chega de perder horas montando fichas manuais, mandando mensagens soltas no WhatsApp ou usando aplicativos engessados. No Treino Inteligente, seus alunos treinam com o <strong>seu logotipo</strong> e você prescreve treinos completos em até 3 minutos.
      </p>

      <!-- Botão CTA -->
      <div style="text-align: center; margin: 32px 0 24px 0;">
        <a href="${linkOferta}" style="display: inline-block; background-color: #10b981; color: #ffffff !important; font-size: 15px; font-weight: 800; text-decoration: none; padding: 18px 36px; border-radius: 12px; box-shadow: 0 6px 20px rgba(16, 185, 129, 0.35); text-transform: uppercase; letter-spacing: 0.5px;">
          TESTAR 3 DIAS GRÁTIS (R$ 0,00 HOJE) →
        </a>
      </div>

      <!-- Garantias -->
      <div style="text-align: center; color: #64748b; font-size: 13px; line-height: 1.5;">
        <span style="color: #10b981; font-weight: bold;">✓</span> R$ 0,00 cobrados hoje &nbsp;|&nbsp; 
        <span style="color: #10b981; font-weight: bold;">✓</span> Cancele em 1 clique &nbsp;|&nbsp; 
        <span style="color: #10b981; font-weight: bold;">✓</span> Sem fidelidade
      </div>

    </div>

    <!-- Rodapé -->
    <div style="background-color: #f1f5f9; border-top: 1px solid #e2e8f0; padding: 24px; text-align: center; color: #64748b; font-size: 12px; line-height: 1.6;">
      <p style="margin: 0 0 6px 0; font-weight: 600; color: #475569;">
        Treino Inteligente · O aplicativo definitivo para Personal Trainers
      </p>
      <p style="margin: 0;">
        Precisa de ajuda ou quer tirar dúvidas? Basta responder diretamente a este e-mail.
      </p>
    </div>

  </div>
</body>
</html>`;

return [{
  json: {
    lead_id: leadAnterior.lead_id,
    nome: leadAnterior.nome,
    primeiro_nome: primeiroNome,
    email: leadAnterior.email,
    whatsapp: leadAnterior.whatsapp,
    whatsapp_formatado: leadAnterior.whatsapp_formatado,
    data_hora: leadAnterior.data_hora,
    rota_recomendada: rotaFinal,
    oferta_nome: ofertaNome,
    perfil_resumo: aiData.perfil_resumo || '',
    score_maturidade: aiData.score_maturidade || 6,
    dor_principal: dor,
    gatilho_conversao: gatilho,
    link_oferta: linkOferta,
    mensagem_whatsapp: msgWhatsapp,
    email_assunto: emailAssunto,
    email_corpo_html: emailCorpoHtml,
    dados_legiveis: leadAnterior.dados_legiveis,
    utm: leadAnterior.utm
  }
}];
